app.post('/api/auth/register', authLimit, async (req, res) => {
  const fullName=String(req.body?.fullName||'').trim().slice(0,100), email = String(req.body?.email || '').trim().toLowerCase(), password = String(req.body?.password || '');
  if(adminEmails.has(email))return res.status(403).json({error:'This email address is not available for public registration.'});
  if(fullName.length<2)return res.status(400).json({error:'Enter your full name.'});
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254) return res.status(400).json({ error: 'Enter a valid email address.' });
  if (password.length < 10 || Buffer.byteLength(password, 'utf8') > 72) return res.status(400).json({ error: 'Use at least 10 characters and no more than 72 UTF-8 bytes.' });
  if(memoryMode){if([...memoryUsers.values()].some(user=>user.email===email))return res.status(409).json({error:'An account with that email already exists.'});const now=new Date(),ends=new Date(now.getTime()+30*24*60*60*1000),user={_id:randomUUID(),fullName,email,role:adminEmails.has(email)?'admin':'customer',passwordHash:await bcrypt.hash(password,12),trialStartedAt:now,trialEndsAt:ends,subscriptionStatus:'trialing',createdAt:now};memoryUsers.set(user._id,user);setSession(req,res,makeToken(user));return res.status(201).json({user:userView(user),trial:trialFor(user),storageMode:'memory'});}
  if (await User.exists({ email })) return res.status(409).json({ error: 'An account with that email already exists.' });
  const now = new Date(), ends = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
  try { const user = await User.create({ fullName,email,role:adminEmails.has(email)?'admin':'customer', passwordHash: await bcrypt.hash(password, 12), trialStartedAt: now, trialEndsAt: ends,subscriptionStatus:'trialing' }); setSession(req,res,makeToken(user)); res.status(201).json({ user:userView(user), trial: trialFor(user),storageMode:'mongodb' }); }
  catch (error) { if (error.code === 11000) return res.status(409).json({ error: 'An account with that email already exists.' }); throw error; }
});
