app.get('/api/admin/audit',account,adminOnly,async(req,res)=>{const {page,limit,skip}=pageArgs(req);if(memoryMode)return res.json({audit:memoryAdminAudit.slice(skip,skip+limit),pagination:pageMeta(memoryAdminAudit.length,page,limit)});const [total,audit]=await Promise.all([AdminAudit.countDocuments({}),AdminAudit.find({}).sort({at:-1,_id:-1}).skip(skip).limit(limit)]);res.json({audit,pagination:pageMeta(total,page,limit)})});
app.get('/api/admin/telemetry',account,adminOnly,async(req,res)=>{const heartbeatCutoff=new Date(Date.now()-120000),activeHeartbeats=memoryMode?[...memoryDevices.values()].filter(d=>new Date(d.lastHeartbeatAt||0)>=heartbeatCutoff).length:await Device.countDocuments({lastHeartbeatAt:{$gte:heartbeatCutoff}});res.json({uptimeSeconds:Math.floor((Date.now()-processStartedAt.getTime())/1000),database:databaseReady&&!memoryMode?'connected':memoryMode?'memory':'unavailable',firebase:{configured:Boolean(firebaseAuth&&(firebaseProjectId||firebaseCredentials?.project_id||process.env.GOOGLE_APPLICATION_CREDENTIALS)),attempted:pushTelemetry.attempted,sent:pushTelemetry.sent,failed:pushTelemetry.failed,lastAttemptAt:pushTelemetry.lastAttemptAt,lastSuccessAt:pushTelemetry.lastSuccessAt,lastError:pushTelemetry.lastError},activeHeartbeats,heartbeatWindowSeconds:120})});
app.get('/api/admin/support-escalations',account,adminOnly,async(req,res)=>{const {page,limit,skip}=pageArgs(req);if(memoryMode){const rows=[...memoryEscalations.values()].filter(item=>new Date(item.expiresAt)>new Date()).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return res.json({escalations:rows.slice(skip,skip+limit).map(({tokenHash,...rest})=>rest),pagination:pageMeta(rows.length,page,limit)})}const filter={expiresAt:{$gt:new Date()}},[total,escalations]=await Promise.all([SupportEscalation.countDocuments(filter),SupportEscalation.find(filter).sort({createdAt:-1,_id:-1}).skip(skip).limit(limit).select('-tokenHash')]);res.json({escalations,pagination:pageMeta(total,page,limit)})});
app.post('/api/admin/support-escalations',account,adminOnly,async(req,res)=>{const deviceId=String(req.body?.deviceId||''),reason=String(req.body?.reason||'').trim().slice(0,500),scopes=[...new Set(Array.isArray(req.body?.scopes)?req.body.scopes:[])];if(!memoryMode&&!mongoose.isValidObjectId(deviceId))return res.status(404).json({error:'Device not found.'});if(!reason||reason.length<12||!scopes.length||scopes.some(scope=>!['location','commands'].includes(scope)))return res.status(400).json({error:'Provide a support reason of at least 12 characters and one valid scope.'});const device=memoryMode?memoryDevices.get(deviceId):await Device.findById(deviceId);if(!device)return res.status(404).json({error:'Device not found.'});const raw=randomBytes(32).toString('base64url'),record={tokenHash:hashCode(raw),actorId:String(req.user._id),actorEmail:req.user.email,deviceId,reason,scopes,usedScopes:[],createdAt:new Date(),expiresAt:new Date(Date.now()+15*60*1000)};if(memoryMode)memoryEscalations.set(record.tokenHash,record);else await SupportEscalation.create(record);await writeAdminAudit(req.user,'support_escalation.created',deviceId,{reason,scopes,expiresAt:record.expiresAt});res.status(201).json({token:raw,deviceId,reason,scopes,expiresAt:record.expiresAt,warning:'Copy this token now. It is shown only once and each scope can be used once.'})});
async function consumeSupportEscalation(req,deviceId,scope){const token=String(req.get('x-support-escalation')||'');if(token.length<40||token.length>80)throw Object.assign(new Error('A valid support escalation token is required.'),{status:403});const tokenHash=hashCode(token),actorId=String(req.user._id),now=new Date();let record;if(memoryMode){record=memoryEscalations.get(tokenHash);if(!record||record.deviceId!==String(deviceId)||record.actorId!==actorId||new Date(record.expiresAt)<=now||!record.scopes.includes(scope)||record.usedScopes.includes(scope))record=null;else record.usedScopes.push(scope)}else record=await SupportEscalation.findOneAndUpdate({tokenHash,deviceId:String(deviceId),actorId,expiresAt:{$gt:now},scopes:scope,usedScopes:{$ne:scope}},{$addToSet:{usedScopes:scope}},{new:true});if(!record)throw Object.assign(new Error('The support escalation token is invalid, expired, used, or missing this scope.'),{status:403});return record}
app.get('/api/admin/devices/:id/location',account,adminOnly,async(req,res)=>{if(!memoryMode&&!mongoose.isValidObjectId(req.params.id))return res.status(404).json({error:'Device not found.'});const d=memoryMode?memoryDevices.get(req.params.id):await Device.findById(req.params.id);if(!d)return res.status(404).json({error:'Device not found.'});try{const escalation=await consumeSupportEscalation(req,d._id,'location');const location=d.lastLocation?.toObject?.()??d.lastLocation;if(!location?.recordedAt)return res.status(404).json({error:'No GPS report is available.'});await writeAdminAudit(req.user,'support_escalation.location_accessed',String(d._id),{reason:escalation.reason});return res.json({deviceId:String(d._id),name:d.name,location})}catch(error){return res.status(error.status||500).json({error:error.message})}});
app.post('/api/admin/devices/:id/command',account,adminOnly,async(req,res)=>{if(!memoryMode&&!mongoose.isValidObjectId(req.params.id))return res.status(404).json({error:'Device not found.'});const d=memoryMode?memoryDevices.get(req.params.id):await Device.findById(req.params.id).select('+fcmToken');if(!d)return res.status(404).json({error:'Device not found.'});const action=String(req.body?.action||''),enabled=req.body?.enabled===undefined?true:req.body.enabled;if(!['full_lockdown_anti_flash','maximum_volume_siren','sim_tamper_alert','locate_now','theft_mode'].includes(action)||typeof enabled!=='boolean')return res.status(400).json({error:'Choose a supported command and boolean value.'});if(action==='full_lockdown_anti_flash'&&enabled&&d.platform!=='Android')return res.status(400).json({error:'Full device lockdown commands require an enrolled Android device.'});try{const escalation=await consumeSupportEscalation(req,d._id,'commands'),stateField={full_lockdown_anti_flash:'fullLockdownEnabled',maximum_volume_siren:'sirenEnabled',sim_tamper_alert:'simTamperAlertEnabled',theft_mode:'theftMode'}[action];if(stateField){d[stateField]=enabled;addEvent(d,'admin_escalated_command_requested',`${action} was requested by an administrator under support escalation.`);await saveDevice(d)}const command=await dispatchDeviceCommand(d,action,enabled);await writeAdminAudit(req.user,'support_escalation.command_requested',String(d._id),{reason:escalation.reason,action,enabled,commandId:command.id});res.status(202).json({command})}catch(error){res.status(error.status||500).json({error:error.message})}});
app.get('/api/phone/state',deviceAuth,async(req,res)=>{const d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub);if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});await touchDeviceHeartbeat(d);res.json({theftMode:Boolean(d.theftMode||d.fullLockdownEnabled),fullLockdownEnabled:Boolean(d.fullLockdownEnabled),sirenEnabled:d.sirenEnabled,simTamperAlertEnabled:Boolean(d.simTamperAlertEnabled),locationSharingEnabled:d.locationSharingEnabled,device:{id:String(d._id),name:d.name,platform:d.platform}})});
app.post('/api/phone/fcm-token',deviceAuth,async(req,res)=>{const token=String(req.body?.token||'').trim();if(token.length<20||token.length>4096)return res.status(400).json({error:'A valid Firebase registration token is required.'});const d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub).select('+fcmToken');if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});if(d.platform!=='Android')return res.status(400).json({error:'Native push registration is currently supported only on Android.'});d.fcmToken=token;addEvent(d,'native_push_registered','A native Android app registered for secure device commands.');await saveDevice(d);res.json({registered:true})});
app.get('/api/phone/commands',deviceAuth,async(req,res)=>{const d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub);if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});await touchDeviceHeartbeat(d);res.json({commands:[...(d.commands||[])].filter(command=>command.status==='queued'||command.status==='sent').map(command=>({id:command.id,action:command.action,enabled:command.enabled,createdAt:command.createdAt}))})});
app.post('/api/phone/commands/ack',deviceAuth,async(req,res)=>{const id=String(req.body?.commandId||''),d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub);if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});const command=(d.commands||[]).find(item=>item.id===id);if(!command)return res.status(404).json({error:'Command not found.'});command.status='acknowledged';command.acknowledgedAt=new Date();addEvent(d,'device_command_acknowledged',`${command.action} command was acknowledged by the native app.`);await saveDevice(d);res.json({acknowledged:true})});
app.post('/api/phone/unpair',deviceAuth,async(req,res)=>{const d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub).select('+fcmToken');if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});d.deviceTokenVersion+=1;d.pairedAt=null;d.fcmToken=undefined;addEvent(d,'phone_unpaired','The phone companion was unpaired.');await saveDevice(d);res.json({ok:true})});
app.post('/api/phone/location', deviceAuth, async (req,res)=>{const d=memoryMode?memoryDevices.get(req.deviceClaims.sub):await Device.findById(req.deviceClaims.sub);if(!d||req.deviceClaims.version!==d.deviceTokenVersion)return res.status(401).json({error:'Phone pairing has expired.'});if(!d.locationSharingEnabled)return res.status(403).json({error:'Location sharing is paused from your dashboard.'}); const {latitude,longitude,accuracy}=req.body||{}; if(!Number.isFinite(latitude)||latitude < -90||latitude>90||!Number.isFinite(longitude)||longitude < -180||longitude>180||!Number.isFinite(accuracy)||accuracy<0||accuracy>100000)return res.status(400).json({error:'Location coordinates are invalid.'}); d.lastLocation={latitude,longitude,accuracy,recordedAt:new Date()};d.lastHeartbeatAt=new Date(); if(!d.lastLocationEventAt||Date.now()-new Date(d.lastLocationEventAt).getTime()>10*60*1000){addEvent(d,'location_received','A GPS location was received from the paired phone.');d.lastLocationEventAt=new Date()} await saveDevice(d);res.json({received:true,recordedAt:d.lastLocation.recordedAt});});
async function resolveSessionUser(req){const token=req.cookies.sg_session;if(!token)throw new Error('No session');const claims=jwt.verify(token,secret,{issuer:'safeguard',audience:'safeguard-web'});if(claims.type!=='account'||claims.demo===true)throw new Error('Invalid session');const user=memoryMode?memoryUsers.get(claims.sub):await User.findById(claims.sub);if(!user||user.suspendedAt||Number(claims.sv||0)!==Number(user.sessionVersion||0))throw new Error('Expired session');return user}
app.get(['/app.html','/overview'],async(req,res)=>{const nextPath=req.path==='/overview'?'/overview':'/app.html';if(!req.cookies.sg_session)return res.redirect(302,`/auth.html?next=${encodeURIComponent(nextPath)}`);try{if(productionMode&&!await connectDatabase())return res.status(503).send('SAFEGUARD storage is not configured. Set MONGODB_URI in your hosting environment.');const user=await resolveSessionUser(req);if(userRole(user)==='admin')return res.redirect(302,'/admin.html');res.type('html').send(appPageHtml)}catch{res.redirect(302,`/auth.html?next=${encodeURIComponent(nextPath)}`)}});
