mongoose.connection.on('disconnected',()=>{databaseReady=false;memoryMode=true});
let mongoRetryDelay=5000,mongoUnavailableLogged=false,databaseConnectPromise=null;
async function connectDatabase(){if(databaseReady&&mongoose.connection.readyState===1&&!memoryMode)return true;if(databaseConnectPromise)return databaseConnectPromise;databaseConnectPromise=(async()=>{try{if(!mongoUrl)throw new Error('MONGODB_URI is required in production.');await mongoose.connect(mongoUrl,{serverSelectionTimeoutMS:2000,socketTimeoutMS:4000,autoIndex:true});await Device.collection.updateMany({ownerId:{$exists:false},owner:{$exists:true}},[{$set:{ownerId:'$owner'}}]);await Promise.all([User.init(),Device.init(),AdminAudit.init(),SupportEscalation.init()]);databaseReady=true;mongoRetryDelay=5000;if(!productionMode&&(memoryUsers.size||memoryDevices.size)){memoryMode=true;console.warn('MongoDB is available, but this process already has memory-mode accounts. Restart to switch storage modes safely.')}else{memoryMode=false;mongoUnavailableLogged=false;console.log('MongoDB connected and indexes ready.')}return true}catch(error){databaseReady=false;memoryMode=!productionMode;if(!mongoUnavailableLogged){console.warn(`${productionMode?'Production database unavailable':'MongoDB unavailable; using process-memory account storage'}. ${error.message}`);mongoUnavailableLogged=true}if(!productionMode){const delay=mongoRetryDelay;mongoRetryDelay=Math.min(mongoRetryDelay*2,60000);const retry=setTimeout(()=>{void connectDatabase()},delay);retry.unref()}return false}finally{databaseConnectPromise=null}})();return databaseConnectPromise}
void connectDatabase();
